expressions.expression:
// Superheat heater PI -> DO:SuperHtr PWM duty 0..1 (gated by heatOK).
superheatSet = static.superheatSet
superheatIn  = static.superheatIn
heatOK       = static.heatOK
ki           = static.kiSuper

err = static.superheatSetSafe - static.superheatIn
// ERROR CLAMP (rig 7/14): a COLD PIPE reads superheat -74 -- not a deficit the
// 300W cartridge can fix. Unclamped, P alone slammed the duty to 1.0 and the
// element overshot to 269.7C (5C from the trip), then sat duty-0 for minutes
// cooling back -- the big superheat swings. The element-temp regulator owns the
// preheat; the PI only ever needed to trim near the setpoint.
err = clamp(err, 0 - 10, 10)
iPrev = static.superI
i = iPrev
duty = 0
// ELEMENT-TEMP REGULATION + superheat PI (rig finding: the cartridge couples heat
// into thin vapor POORLY -- dry/low-flow the surface just soars, and the old 180C
// trip fired before any superheat showed). Duty = MIN of two demands:
//   (1) the superheat PI -- the real control, meaningful once vapor flows
//   (2) an element-temp P regulator holding the cartridge at superHtrRegC (200C)
// Startup: (2) rules -- the element preheats REGULATED at ~200C from the moment the
// blower is turning. As vapor flow builds it carries the heat away, the element
// cools, (2) releases, and the superheat PI takes over seamlessly. The regulation IS
// the dry-fire protection (the old blowerMinRpm wait is gone); superHtrMax (250C)
// stays as the hard backstop.
if ( static.heatOK and (static.blowerCmdRpm >= static.blowerRampRpm0) ) then
    // FLOW FEEDFORWARD: duty operating point scales with vapor mass flow (see kShFF).
    // The PI trims around it; the integral may pull NEGATIVE to cancel excess FF.
    dutyFF = static.kShFF * static.blowerCmdRpm / 1000
    i = iPrev + static.kiSuper * err * static.dtReal
    i = clamp(i, 0 - 0.4, 0.4)
    duty = dutyFF + static.kpSuper * err + i
    if ( duty > 1 ) then
        duty = 1
        i = iPrev
    endif
    if ( duty < 0 ) then
        duty = 0
        i = iPrev
    endif
    elem = clamp(static.kpShElem * (static.superHtrRegC - static.ySuperHtrTemp), 0, 1)
    static.shElemLim = 0
    if ( elem < duty ) then
        duty = elem
        i = iPrev    // element regulator is limiting -> hold the PI integral (anti-windup)
        static.shElemLim = 1
    endif
else
    i = 0
    static.shElemLim = 0
endif
static.superI = i
static.superDuty = duty
"DO:SuperHtr" = duty

// ===== CONDENSATE -- single point sensor, pump-to-dry =====
// No separate catch tank: condensate collects in the bottom TUBE of the HX. One
// point-level sensor ~3/4 up the tube (AI:CondLevel > condLevelThresh -> yCondHigh)
// starts the condensate pump. The flow meter is on the PUMP OUTLET, so it directly
// meters the distillate leaving. The pump runs until the tube is DRY: when it sucks
// air the meter pulses stop (yCondFlow ~ 0) -- that is the empty signal. The volume
// pumped per cycle is the distillate batch; batch / fill-time is the production rate.
dt = static.dtReal
cdt = dt
if ( static.simEnable ) then
    cdt = dt * static.simSpeed
endif

// derive the flow RATE from the cumulative meter TOTAL (count/K) -- ONE counter, no
// second channel. Windowed over condRateWin so the per-tick pulse coarseness averages
// out; held between updates (like the old hardware window). yCondFlow is L/min. ----
static.condRateWinT = static.condRateWinT + cdt
if ( static.condRateWinT >= static.condRateWin ) then
    static.yCondFlow = (static.yCondTotal - static.condRateWinTot) / static.condRateWinT * 60
    static.condRateWinTot = static.yCondTotal
    static.condRateWinT = 0
endif

// ---- TOTALIZER-WINDOW production rate: the batch rate (below) needs a healthy
// level sensor to cycle the pump cleanly; a stuck-wet CondLevel micro-cycles it
// and no batch ever reaches condRateMinML -- the control stays blind even with
// the meter counting real flow. The cumulative count over a long window needs no
// cycles at all. Both update the SAME condRateLpm/condHaveRate; batches simply
// refresh it more precisely when they do land. Gated >= 5ml so a truly dead
// meter still leaves condHaveRate clear (-> seek cap + condMeterErr warning). ----
static.prodWinT = static.prodWinT + cdt
if ( static.prodWinT >= static.prodWinS ) then
    winMl = (static.yCondTotal - static.prodWinTot) * static.condCalFactor * 1000
    winLpm = (winMl / 1000) / (static.prodWinT / 60)
    if ( winMl >= 5 ) then
        static.condHaveRate = 1     // meter has PROVEN itself this boot
    endif
    // BURST-AVERAGED rate (rig 7/15 evening): production reaches the meter as
    // PUMP-OUT BURSTS with silence between. Direct window assignment whipsawed:
    // burst windows tripped the plausibility discard while the quiet windows
    // dragged the rate to 0.004 as the user watched real water pump out. Every
    // window now feeds a time-weighted EMA over prodAvgS -- bursts and quiet
    // windows AVERAGE to the true production rate. RUN only; winLpm clamped
    // (not discarded) so a big burst counts as a big burst.
    if ( (static.condHaveRate >= 0.5) and (static.mvrPhase >= 4) ) then
        winLpm = clamp(winLpm, 0, 0.5)
        static.condRateLpm = static.condRateLpm + (winLpm - static.condRateLpm) * clamp(static.prodWinT / static.prodAvgS, 0, 1)
    endif
    static.prodWinTot = static.yCondTotal
    static.prodWinT = 0
endif
// FAST production estimate -- CYCLE-SYNCED (rig 7/22): fixed 60s windows ALIASED
// against the 400-750s flow-follow pump cycles (prodFast swung 0.19<->0.47 while
// true per-cycle production sat flat at 0.46 -- the blower hunted +/-900rpm
// chasing it). The window now closes at each PUMP-OFF edge: the reservoir is in
// the same just-emptied state cycle to cycle, so volume/period is EXACT -- no
// filter needed to un-alias it. prodFastWinS (300) is only the CAP (continuous
// pumping / stall); prodFastMinS ignores micro-cycles. NO condHaveRate wait
// (flow past the meter IS proof). Outside RUN: re-anchor, decay to 0.
if ( static.mvrPhase >= 4 ) then
    static.prodFastWinT = static.prodFastWinT + cdt
    pumpOffEdge = (static.prodFastPmPrev >= 0.5) and (static.condPumpOn < 0.5)
    if ( (pumpOffEdge and (static.prodFastWinT >= static.prodFastMinS)) or (static.prodFastWinT >= static.prodFastWinS) ) then
        fastLpm = clamp(((static.yCondTotal - static.prodFastTot) * static.condCalFactor) / (static.prodFastWinT / 60), 0, 0.5)
        static.prodFast = static.prodFast + (fastLpm - static.prodFast) * clamp(static.prodFastWinT / static.prodFastAvgS, 0, 1)
        static.prodFastTot = static.yCondTotal
        static.prodFastWinT = 0
    endif
else
    static.prodFastWinT = 0
    static.prodFastTot = static.yCondTotal
    static.prodFast = 0
endif
static.prodFastPmPrev = static.condPumpOn

// ---- steam vent (unchanged): vent steam/air at startup until the outlet is liquid.
// The flow meter no longer depends on this -- the level sensor + pump gate it. ----
condLiq = static.condLiquid
if ( static.yCondTemp < static.condLiquidTemp ) then
    condLiq = 1
endif
if ( static.yCondTemp > (static.condLiquidTemp + 2) ) then
    condLiq = 0
endif
if ( static.runSystem == 0 ) then
    condLiq = 0
endif
static.condLiquid = condLiq

// ---- STARTUP NON-CONDENSABLE (air) PURGE vent. The evaporator/HX starts full of AIR.
// Hold the vent OPEN while the system warms so the blower pushes that air out; once the
// blower-out vapor reaches steam temperature the system is pure steam -> CLOSE the vent
// so we stop bleeding steam. Hysteresis on yVaporOut (the blower-OUT temp) so it can't
// chatter at the threshold, and it only purges once the blower is running (phase>=HEAT).
// (Independent of condLiquid, which is the condensate-outlet LIQUID gate the sim uses.) ----
vent = static.ventOpen
// ventDone LATCH: the air purge happens ONCE per run. After the vent closes, a
// mid-run upset that cools yVaporOut back below ventOpenTemp must NOT re-open it
// (it did on the rig 7/13 -- re-bled steam right while the system was struggling).
if ( (static.mvrPhase >= 3) and (static.yVaporOut < static.ventOpenTemp) and (static.ventDone < 0.5) ) then
    vent = 1
endif
if ( static.yVaporOut > static.ventCloseTemp ) then
    if ( vent >= 0.5 ) then
        static.ventDone = 1
    endif
    vent = 0
endif
// AIR-ACCUMULATION PURGE (rig 7/15 log 154015): the steam side ran 1.5-3 psi
// ABOVE Psat of its ~100C temperature -- NON-CONDENSABLE AIR blanketing the
// condensing surface. The pressure-derived deltaT looked healthy (air inflates
// the pressure) while the true thermal dT was ~0 and production sat at 0.004.
// Feed water carries dissolved air in continuously, so this recurs by design:
// when RUN production stalls below prodStallLpm at temp for prodStallS, PULSE
// the vent for ventPulseS to dump the blanket; repeat while stalled. (The
// manual remedy that recovered the rig, on a timer.)
stalled = (static.mvrPhase >= 4) and (static.prodMeas < static.prodStallLpm) and (static.yEvapTemp >= (static.evapTempSetSafe - 3))
if ( stalled ) then
    static.ventStallT = static.ventStallT + cdt
else
    static.ventStallT = 0
endif
if ( stalled and (static.ventStallT > static.prodStallS) ) then
    vent = 1
endif
if ( static.ventStallT > (static.prodStallS + static.ventPulseS) ) then
    static.ventStallT = 0
endif
// THERMAL RELIEF (rig 7/15 stuck-hot deadlock): once the whole discharge path
// superheats, nothing condenses and the blower just churns the same steam hotter
// (vapor-out rode 110-138C with production at 0.004). Venting dumps the hot charge
// and pulls fresh saturated vapor through -- the manual remedy that recovered the
// rig. Overrides the ventDone latch (this is RELIEF, not the air purge).
if ( static.yVaporOut > static.ventReliefC ) then
    static.ventRelief = 1
endif
if ( static.yVaporOut < (static.ventReliefC - 10) ) then
    static.ventRelief = 0
endif
if ( static.ventRelief >= 0.5 ) then
    vent = 1
endif
// NO VENT VALVE FITTED (rig 7/22): only the needle bleed exists -- force the
// state CLOSED+DONE so no control logic waits on, boosts for, or stands down
// during a vent that cannot happen. (Sim keeps modeling the vent.)
if ( (static.ventFitted < 0.5) and (static.simEnable < 0.5) ) then
    vent = 0
    static.ventDone = 1
endif
if ( static.runSystem == 0 ) then
    vent = 0
    static.ventDone = 0
    static.ventRelief = 0
    static.ventStallT = 0
endif
static.ventOpen = vent
"DO:VentValve" = vent

// ---- pump state machine: ACCUMULATE (off) -> sensor trip -> PUMP until DRY ----
static.condCycleSec = static.condCycleSec + cdt          // empty-to-empty fill timer
pump = static.condPumpOn
flowMl = static.yCondFlow * 1000 * cdt / 60              // ml past the meter this tick
if ( static.runSystem == 0 ) then
    pump = 0
    static.condPumpRunSec = 0
    static.condLowFlowSec = 0
    static.condPumpOnAccS = 0
    static.condMeterErr = 0
    static.condAccTot0 = static.yCondTotal
    static.condTimedMode = 0
    static.condTimedOn = 0
    static.condTimedT = 0
    static.condSensErr = 0
endif
if ( static.runSystem == 1 ) then
    if ( pump == 0 ) then
        if ( static.yCondHigh ) then
            pump = 1                                     // tube hit the sensor -> empty it
            static.condBatchRaw = 0
            static.condTotalAtStart = static.yCondTotal
            static.condPumpRunSec = 0
            static.condLowFlowSec = 0
        endif
    else
        static.condPumpRunSec = static.condPumpRunSec + cdt
        // MEASUREMENT-DEAD watch: accumulate total pump-ON time; a REAL batch resets
        // it below. Endless micro-cycles (pump restarts on a stuck-wet level sensor,
        // or an airlocked pump moves nothing past the meter) never trip the 120s
        // continuous cap -- this cumulative one catches them and warns the operator
        // (production control is BLIND while this is happening).
        static.condPumpOnAccS = static.condPumpOnAccS + cdt
        static.condBatchRaw = static.condBatchRaw + flowMl
        if ( static.yCondFlow < static.condEmptyFlow ) then
            static.condLowFlowSec = static.condLowFlowSec + cdt
        else
            static.condLowFlowSec = 0
        endif
        emptied = 0
        if ( static.condPumpRunSec > static.condPumpMinRun and static.condLowFlowSec > static.condEmptyDebounce ) then
            emptied = 1                                  // (1) meter rate dropped to ~0 on air -> tube dry (primary)
        endif
        if ( static.condBatchRaw * static.condCalFactor > static.condBatchMaxML ) then
            emptied = 1                                  // (2) metered batch implausibly large -> stop (meter kept counting)
        endif
        if ( static.condPumpRunSec > static.condPumpMaxRun ) then
            emptied = 1
            static.condPumpFault = 1                     // (3) hard time cap -> stop + flag (never went dry)
        endif
        if ( emptied ) then
            pump = 0
            if ( static.condUseTotalizer ) then
                static.condBatchMl = (static.yCondTotal - static.condTotalAtStart) * static.condCalFactor * 1000   // EXACT: pulses this cycle / K, cal-corrected
            else
                static.condBatchMl = static.condBatchRaw * static.condCalFactor              // integrated windowed rate
                static.condProduct = static.condProduct + static.condBatchMl                 // accumulate
            endif
            // RATE SANITY (rig 7/13): micro-batches (pump prime lag trips the dry
            // detect at ~1ml) must NOT reset the fill timer or make a rate; and an
            // impossible rate (bad cycle time) must be discarded, not believed.
            realBatch = 0
            if ( static.condBatchMl >= static.condRateMinML ) then
                realBatch = 1
            endif
            if ( realBatch and (static.condCycleSec > 0.1) and (static.prodFromTotal < 0.5) ) then
                rawRate = (static.condBatchMl / 1000) / (static.condCycleSec / 60)
                if ( rawRate <= static.condRateMaxLpm ) then
                    static.condRateLpm = rawRate
                    static.condHaveRate = 1
                endif
            endif
            if ( realBatch ) then
                static.condCycleSec = 0
                static.condPumpOnAccS = 0
                static.condMeterErr = 0
                static.condAccTot0 = static.yCondTotal
            endif
        endif
    endif
endif
// SENSOR-BAD vs METER-DEAD classification: the pump has cycled condMeterFaultS
// cumulative without one real batch. If the METER counted flow in that time, the
// LEVEL SENSOR is the liar (fog film -> stuck wet): latch condSensErr and (if
// condTimedEn) switch to TIMED pumping for the rest of the run. Meter counted
// nothing -> condMeterErr (measurement dead) as before.
if ( (static.runSystem == 1) and (static.condPumpOnAccS > static.condMeterFaultS) ) then
    accMl = (static.yCondTotal - static.condAccTot0) * static.condCalFactor * 1000
    if ( accMl >= 5 ) then
        static.condSensErr = 1
        if ( static.condTimedEn >= 0.5 ) then
            static.condTimedMode = 1
        endif
    else
        static.condMeterErr = 1
    endif
endif
// TIMED PUMP FALLBACK: overrides the sensor-driven machine EVERY tick (the stuck
// sensor keeps trying to restart the pump; this owns the final say). ON-phase
// start does the same bookkeeping as a sensor start, so the machine's dry-detect
// and batch metering still work inside each timed ON window.
// condTimedAlways: timed flow-follow as the PRIMARY strategy (not just fallback)
if ( (static.runSystem == 1) and (static.condTimedAlways >= 0.5) and (static.mvrPhase >= 4) ) then
    static.condTimedMode = 1
endif
if ( (static.runSystem == 1) and (static.condTimedMode >= 0.5) ) then
    // FLOW-FOLLOW (rig-proven): probe every condTimedOffS; run at least condTimedOnS;
    // then KEEP running while the 5s-avg meter flow holds above condTimedMinLpm --
    // the METER decides when the reservoir is empty, not the fogged level sensor.
    static.condFlowAvg = static.condFlowAvg + (static.yCondFlow - static.condFlowAvg) * clamp(cdt / 5, 0, 1)
    static.condTimedT = static.condTimedT + cdt
    if ( (static.condTimedOn >= 0.5) and (static.condTimedT >= static.condTimedOnS) and (static.condFlowAvg < static.condTimedMinLpm) ) then
        static.condTimedOn = 0
        static.condTimedT = 0
    endif
    if ( (static.condTimedOn < 0.5) and (static.condTimedT >= static.condTimedOffS) ) then
        static.condTimedOn = 1
        static.condTimedT = 0
        static.condFlowAvg = static.condTimedMinLpm * 2
        static.condBatchRaw = 0
        static.condTotalAtStart = static.yCondTotal
        static.condPumpRunSec = 0
        static.condLowFlowSec = 0
    endif
    pump = static.condTimedOn
endif
static.condPumpOn = pump
"DO:CondPump" = pump

// TOTALIZER method (condUseTotalizer=1): lifetime product = cumulative pulse count
// straight off the pump-outlet meter (count/K), exact + rollover-safe -- no
// windowed-rate integration error. The rate method (=0) accumulates per batch above. ----
if ( static.condUseTotalizer ) then
    static.condProduct = static.yCondTotal * static.condCalFactor * 1000
endif

// ---- FEED-SIDE inventory dead-reckon: feed IN minus vapor OUT. Vapor leaves the
// evaporator CONTINUOUSLY (production), not in pump bursts -- use the measured
// production rate (or the blower estimate before the first batch). ----
feedInMl = static.feedCmdRpm * static.feedStepsPerRev * static.feedLPerStep * 1000 * cdt / 60
// SWELL DISCRIMINATOR: 60s EMA of FORWARD feed rate -- Interlocks only warns
// high-level when this shows the feed actually put water in recently
static.feedRecentLpm = static.feedRecentLpm + (clamp(static.feedCmdRpm, 0, 1000) * static.feedStepsPerRev * static.feedLPerStep - static.feedRecentLpm) * clamp(cdt / 60, 0, 1)
static.blowerProdEst = static.heatOK * clamp(static.prodPerRpm * static.blowerRpmSafe * clamp((static.yEvapTemp - 95) / 5, 0, 1), 0, 1)
vaporRate = static.blowerProdEst
if ( static.condHaveRate and (static.mvrPhase >= 4) ) then
    vaporRate = static.condRateLpm                         // measured rate counts as vapor-out only in RUN (producing)
endif
vaporOutMl = vaporRate * 1000 * cdt / 60
// concentrate BLOWDOWN purge: feed runs ~blowdownFrac above distillate; that excess
// leaves as LIQUID via the BlowdownValve (NOT as vapor). Subtract it so the inventory
// balances -- else the level dead-reckon (and the real evaporator) creep up. RUN only.
blowdownMl = 0
if ( static.mvrPhase >= 4 ) then
    blowdownMl = static.blowdownFrac * vaporRate * 1000 * cdt / 60
endif
// dead-reckon + the LEARNED rate-bias correction (the anchors teach it below): without
// this, a biased flow meter makes feedIn/vaporOut disagree with reality at a steady
// RATE, and position snaps alone can't hold against a rate error.
static.feedInvEst = clamp(static.feedInvEst + feedInMl - vaporOutMl - blowdownMl + static.levelBiasLpm * 1000 * cdt / 60, 0, 20000)
// CLAMP the dead-reckon to be CONSISTENT with the wet/dry sensor states every tick: a
// wet sensor means the level is at/above its mark, a dry one means below. So feedInvEst
// is bounded into the sensor-consistent range -- the calibrated feed pump dead-reckons
// within, the sensors correct any drift continuously (not just at crossings). PRIME on.
if ( static.senderOK ) then
    // PLATEAU-CHANGE FUSION (measured cal table): when the decoded plateau CHANGES,
    // the level just crossed the boundary between the two plateaus -- best estimate =
    // the midpoint of the old/new plateau centers. Each snap's innovation teaches the
    // rate-bias observer; the window clamp bounds the estimate inside the plateau span.
    if ( (static.mvrPhase >= 1) and (static.levelStepPrev >= 0) and (static.yEvapLevRaw != static.levelStepPrev) ) then
        snapML = (static.yEvapLevRaw + static.levelStepPrev) * 0.5
        static.levelBiasLpm = clamp(static.levelBiasLpm + static.kLevelBias * (snapML - static.feedInvEst), 0 - 0.05, 0.05)
        static.feedInvEst = snapML
        if ( static.yEvapLevRaw > static.levelStepPrev ) then
            static.feedStallML = 0
        endif
    endif
    static.levelStepPrev = static.yEvapLevRaw
    if ( static.mvrPhase >= 1 ) then
        wLo = static.yEvapLevRaw - static.senderSpanML
        wHi = static.yEvapLevRaw + static.senderSpanML
        // window clamps do NOT teach the bias: plateau CENTERS are estimates (the
        // spans were only sparsely measured), so teaching against the window bound
        // over-cooks the bias and drags the hold off-center. Only the EDGE snaps
        // (well-defined physical crossings) teach.
        if ( static.feedInvEst < wLo ) then
            static.feedInvEst = wLo
        endif
        if ( static.feedInvEst > wHi ) then
            static.feedInvEst = wHi
        endif
    endif
endif
// ---- FEED-STALL watch (rig 7/14): feed commanded at fill rate but the sender
// never steps UP = the pump is not delivering (or the sender is stuck). Counts
// dead-reckoned feed; an upward plateau step (the fusion snap above) resets it;
// Interlocks latches evapLevelErr past feedStallMaxML. ----
if ( (static.mvrPhase >= 2) and (static.feedCmdRpm >= static.feedStallRpm) ) then
    // NET of measured production (rig 7/21 false trips): at high production the feed
    // legitimately runs at fill-rate FOREVER while the level holds steady -- gross
    // accumulation hit 1500ml every ~6min and tripped a healthy run. On a net basis
    // feed matching production accumulates ~nothing; a dead feed line still
    // accumulates at full rate (production collapses while the boiler drains).
    stallProd = static.prodMeas
    if ( static.prodFast > 0 ) then
        stallProd = static.prodFast
    endif
    static.feedStallML = clamp(static.feedStallML + feedInMl - (stallProd * 1000 * cdt / 60), 0, 100000)
endif
// ---- INPUT-SIDE production estimate (prodUseInput option): boil-off = the EXACT
// calibrated feed IN minus the sender-anchored level CHANGE over a long window.
// Nothing from the condensate meter. RUN only; window state re-seeded outside RUN
// and at run start (MVR System). Clamped to plausible; negative transients -> 0. ----
if ( static.mvrPhase >= 4 ) then
    static.prodInFeedMl = static.prodInFeedMl + feedInMl
    static.prodInWinT = static.prodInWinT + cdt
    // GUARDED window length: below ~60s a window sees only a few ml of feed and
    // quantizes to garbage (rig 7/13: prodInWinS got set to 10 via the UI -- the
    // estimate read 0 all run, the integral ratcheted the blower to max, and
    // plateau-snap windows spiked 0.5 L/min crashing it back).
    effWin = clamp(static.prodInWinS, 60, 3600)
    if ( static.prodInWinT >= effWin ) then
        inMl = static.prodInFeedMl - (static.feedInvEst - static.prodInLvl0)
        static.prodInLpm = clamp((inMl / 1000) / (static.prodInWinT / 60), 0, static.condRateMaxLpm)
        static.prodInHave = 1
        static.prodInFeedMl = 0
        static.prodInLvl0 = static.feedInvEst
        static.prodInWinT = 0
    endif
else
    static.prodInWinT = 0
    static.prodInFeedMl = 0
    static.prodInLvl0 = static.feedInvEst
endif
// METER CAL is MANUAL (condCalFactor): the production measurement also feeds the blower
// production control, so an auto-cal here forms a loop (cal -> measured prod -> blower ->
// actual prod -> meter -> cal) that destabilizes. Calibrate condCalFactor once against
// the feed pump at steady level: at hold, distillate = feed/(1+blowdownFrac), so set
// condCalFactor = (feed/(1+blowdown)) / (raw metered rate).
if ( (static.mvrPhase == 1) or (static.emptying >= 0.5) ) then
    static.purgeOutML = static.purgeOutML - feedInMl    // PURGE: feedInMl is negative (reverse) -> accumulate ml out
endif

// Production control: trim the blower (compressor throughput) to hold the TARGET
// distillate rate. Measured production now comes from the condensate BATCHES: each
// pump-to-dry cycle meters a known distillate volume, and volume / fill-time is the
// average production rate -- the only rate a single point-level sensor can give. It
// updates once per empty cycle (condRateLpm, condHaveRate from CondensatePump) and is
// held between cycles; before the first batch the blower holds its nominal rpm.
cdt = static.dtReal
if ( static.simEnable ) then
    cdt = cdt * static.simSpeed
endif
// PRODUCTION MEASUREMENT SOURCE: output (condensate meter, default) or the
// INPUT side (prodUseInput=1: calibrated feed - level change) when the output
// meter can't be trusted. Everything downstream (integral, floors, caps, seek)
// is identical -- only where the number comes from changes.
haveMeas = static.condHaveRate
measProd = static.condRateLpm
if ( static.prodUseInput >= 0.5 ) then
    haveMeas = static.prodInHave
    measProd = static.prodInLpm
endif
if ( haveMeas ) then
    // slower smoothing (tau ~50s, was ~20s): prodMeas feeds BOTH the blower integral
    // and the feed feed-forward -- measurement jumps became actuator slams
    static.prodMeas = static.prodMeas + (measProd - static.prodMeas) * clamp(cdt * 0.02, 0, 1)
endif
// LOOP MEASUREMENT = the FAST estimate (rig 7/21): the integral steering on
// double-smoothed prodMeas kept climbing on stale data (production was already
// over set before the number said so) and then unwound the overshoot at the
// same timid rate. prodFast (60s windows, ~60-90s latency) sees it in time.
pmG = static.prodMeas
if ( static.prodFast > 0 ) then
    pmG = static.prodFast
endif
// Blower target in RUN, vent CLOSED (while venting production is unmeasurable and
// the target is FROZEN -- the old integrator wound 1500->3514 chasing vented steam):
//  - BEFORE the first condensate batch there is no measured rate yet, so the target
//    used to sit frozen at the nominal 1500 (rig 7/13) -- now it PRESSURE-SEEKS:
//    climb while the suction holds above evapPressMin+margin. More rpm = more
//    throughput as long as the boil keeps up; suction dropping = the ceiling.
//  - AFTER batches land, the production integral chases prodSetSafe, but never
//    raises the target while the command lags (anti-windup) or the suction is at
//    the floor (production is heat-limited -- the floor IS the achievable max).
//  - Either mode: suction below the floor actively backs the target off.
// MINIMUM LIFT (rig 7/14): deltaT ~1C = PR ~1 -- the HX has no driving dT, the
// loop moves no heat, and the sealed system slowly pressurizes. The compressor's
// first job is LIFT: below deltaTMin, RAISE the target (HEAT included -- this must
// work before RUN's production control takes over). Outranks the superheat rescue
// (gated on adequate lift below): at PR~1 compression work is tiny, wet-comp risk
// minimal, and without lift nothing else can work.
// ...but NOT while measured production already meets the setpoint (rig 7/15
// 'Slow_Roll' log): with eTset=102 squeezing dT below deltaTMin, the lift raise
// (25rpm/s up) fought the production integral (down) in a ~150s limit cycle
// while the machine over-produced at 0.29 vs 0.12 set. Lift exists to escape
// NO-CONDENSATION -- a healthy metered production IS proof the lift suffices.
if ( static.autoBlow and (static.mvrPhase >= 3) and (static.ventOpen < 0.5) and (static.yEvapTemp >= (static.evapTempSetSafe - 3)) and (static.deltaT < static.deltaTMin) and (static.blowerRpmSet < static.blowerSeekMaxRpm) and (static.yVaporOut < (static.vaporOutSoft - 5)) and ((static.condHaveRate < 0.5) or (pmG < static.prodSetSafe)) ) then
    static.blowerRpmSet = static.blowerRpmSet + static.blowerSeekRpmS * cdt
endif
// BOOST HAND-OFF: the tick the vent closes, SEED the target at the current
// command -- stepping 2500 -> 1500 crashed the progress on the rig (VaporOut
// decayed 94 -> 88, superheat went negative, and the seek stalled on the very
// sag the drop caused). Hold the boost rpm and glide DOWN to the natural
// operating point under production/pressure control instead.
if ( (static.ventPrev >= 0.5) and (static.ventOpen < 0.5) and (static.mvrPhase >= 3) and (static.blowerCmdRpm > static.blowerRpmSet) ) then
    static.blowerRpmSet = static.blowerCmdRpm
endif
static.ventPrev = static.ventOpen
if ( static.autoBlow and (static.mvrPhase >= 4) and (static.ventOpen < 0.5) ) then
    rpm = static.blowerRpmSet
    if ( haveMeas ) then
        err = static.prodSetSafe - pmG
        // RAISE DEADBAND: within kProdBand of set, stop climbing -- momentum +
        // measurement lag close the gap (climbing to zero error = overshoot)
        if ( (err > 0) and (err < static.kProdBand) ) then
            err = 0
        endif
        if ( (err > 0) and (static.blowerCmdRpm < (static.blowerRpmSet - 50)) ) then
            err = 0
        endif
        if ( (err > 0) and (static.yEvapPress < static.evapPressMin) ) then
            err = 0
        endif
        // ...and not while superheat is COLLAPSED either (same pause the seek has):
        // more rpm into a plant that can't superheat the current flow just digs the
        // hole deeper (rig 7/13: integral climbed 3300->4000 with superheat at -5).
        if ( (err > 0) and (static.superheatIn < (static.minSuperheat + 1.0)) ) then
            err = 0
        endif
        // ...and never raise while the discharge is OVERHEATING: high vapor-out
        // with low production = the blower is heating the vapor, not pumping it
        // (rig 7/15: every other gate read green while it wound to 4000)
        if ( (err > 0) and (static.yVaporOut > (static.vaporOutSoft - 5)) ) then
            err = 0
        endif
        // UP-RATE CAP: a big deficit (restart, prodFast reset) is not a license
        // to rocket -- 0.15 caps the climb at 3rpm/s; the plant gates rule anyway
        if ( err > 0.15 ) then
            err = 0.15
        endif
        // ASYMMETRIC UNWIND (rig 7/21): overshoot falls kProdDown x faster than
        // shortfall climbs -- 2860->2100 in ~90s instead of ~6min of overselling
        if ( err < 0 ) then
            err = err * static.kProdDown
        endif
        rpm = rpm + static.kProd * err * cdt
    endif
    // seek CAPPED at blowerSeekMaxRpm, and PAUSED while superheat is marginal --
    // superheat collapsing is the other 'blower outpacing the plant' signal (the
    // 300W cartridge can't superheat unlimited mass flow).
    if ( (haveMeas == 0) and (static.yEvapPress > (static.evapPressMin + 0.3)) and (rpm < static.blowerSeekMaxRpm) and (static.superheatIn > (static.minSuperheat + 1.0)) and (static.yVaporOut < (static.vaporOutSoft - 5)) ) then
        rpm = rpm + static.blowerSeekRpmS * cdt
    endif
    // SUPERHEAT RESCUE (rig 7/14): pausing the raise is not enough -- when superheat
    // sits collapsed at speed+temp (vent closed), actively BACK the target off toward
    // the run floor. Less mass flow = more superheat per watt; the 20s wet-comp
    // debounce then has something that recovers instead of something that trips.
    if ( (static.ventOpen < 0.5) and (static.superheatIn < (static.minSuperheat + 0.5)) and (static.yEvapTemp >= (static.evapTempSetSafe - 5)) and (static.deltaT >= static.deltaTMin) ) then
        rpm = rpm - static.blowerSeekRpmS * cdt
    endif
    // VAPOR-OUT FOLD-BACK, PROPORTIONAL (rig 7/15 pm): the discharge climbs 20C in
    // 30s -- the fixed-rate version sawtoothed 2755<->300 and still let a 142C spike
    // trip. Backoff speed scales with the excess (0.3x just above, 3x cap at +30C),
    // so the blower SETTLES at the temperature-limited rpm instead of hunting.
    if ( static.yVaporOut > static.vaporOutSoft ) then
        rpm = rpm - static.blowerSeekRpmS * cdt * clamp((static.yVaporOut - static.vaporOutSoft) / 10, 0.3, 3)
    endif
    if ( static.yEvapPress < static.evapPressMin ) then
        rpm = rpm - static.blowerSeekRpmS * cdt
    endif
    // TURNDOWN FLOOR: never below blowerRunMinRpm once running -- below ~2000 there
    // is no meaningful vapor flow and everything the run built unwinds.
    rpm = clamp(rpm, static.blowerRunMinRpm, static.blowerMaxRpm)
    static.blowerRpmSet = rpm
endif

// Feed follows production (mass balance): feed in = distillate out + blowdown.
// Tracks MEASURED production. rpm = (L/min) / (stepsPerRev * LPerStep). Active
// from HEAT (phase 3); PRIME feed is handled by the startup state machine.
// RESTRUCTURED FLAT (7/21): the old single big if(autoFeed...) block hit the
// transpiler deep-nesting hoist -- the cold-fold / min-feed / high-cut / slew
// sections compiled OUTSIDE the guard, so with autoFeed off or phase < 3 they
// still ran and pushed 0/0 garbage into feedRpmSet. Every section now carries
// the fActive guard explicitly; nothing trails a nested block.
fActive = 0
if ( static.autoFeed and (static.mvrPhase >= 3) ) then
    fActive = 1
endif
lpmPerRpm = static.feedStepsPerRev * static.feedLPerStep
maxFeedLpm = static.feedRpmMax * lpmPerRpm
// FEED-FORWARD from the FAST meter estimate (rig 7/21): prodMeas lags ~10min --
// under-fed the production surge (level 2600->1500), wound the trim up, then
// overfed to 2900 sawtoothing. prodFast responds in ~2-3min. Falls back to the
// slow prodMeas until the fast estimate exists (first window after RUN entry).
feedFF = static.prodMeas * (1 + static.blowdownFrac)
if ( static.prodFast > 0 ) then
    feedFF = static.prodFast * (1 + static.blowdownFrac)
endif
// ADAPTIVE BASE BLEND (rig 7/21 evening): prodFast windows catch 1-2 pump
// bursts and bounce +/-30%, so the FF center wandered and the raw-edge
// overrides ran bang-bang 425<->190rpm -- every 425 slam a cold slug the
// makeup PI fought at full duty. feedBaseLpm (slow EMA of commanded feed,
// learned below) is the steadier truth; blend it in as RUN-time confidence
// (fBaseW 0 -> 0.7 over feedBaseRampS) grows, and soften the overrides with
// the same confidence (fCorr): swings shrink toward ripples around the base.
fBaseW = 0
if ( (static.feedBaseLpm > 0) and (static.mvrPhase >= 4) ) then
    fBaseW = clamp(static.feedBaseT / static.feedBaseRampS, 0, 0.7)
endif
feedFF = feedFF * (1 - fBaseW) + static.feedBaseLpm * fBaseW
fCorr = 1 - 0.6 * fBaseW
feedLpm = feedFF
if ( fActive and static.haveEvapLevel ) then
    // ANALOG-SENDER PI (P ~10x I, per bench tuning): P on the FUSED level (sender
    // step-edges + feed dead-reckon) fills the warm-up AND damps the swing. P acts
    // only OUTSIDE a +/-1-step deadband (~200mL): within a sender step the estimate
    // cannot resolve the true level. P is a TRIM, not a fire hose (levelPMax).
    lvlErr = static.evapLevelSet - static.feedInvEst
    levelP = 0
    if ( lvlErr > static.levelDeadML ) then
        levelP = static.kFeedLevel * (lvlErr - static.levelDeadML)
    endif
    if ( lvlErr < (0 - static.levelDeadML) ) then
        levelP = static.kFeedLevel * (lvlErr + static.levelDeadML)
    endif
    levelP = clamp(levelP, 0 - static.levelPMax, static.levelPMax)
    // The TIGHT hold is the EvapMid switch integral: a perfect 1-bit sensor placed
    // exactly AT the setpoint. Integrate ONLY inside the deadband (where P is
    // silent); bounds -0.05..feedTrimMax (a bias shaver, not a fire hose).
    iDir = 1
    if ( static.yEvapMid ) then
        iDir = 0 - 1
    endif
    // (trim wind-up also gated below: not in HEAT above the reduced fill target --
    // it was the thing that topped the cold charge off to the mark)
    if ( (lvlErr > (0 - static.levelDeadML)) and (lvlErr < static.levelDeadML) and ((static.mvrPhase >= 4) or (static.yEvapLevRaw < (static.evapMidMark - static.fillStopML))) ) then
        static.feedLevelTrim = clamp(static.feedLevelTrim + static.kFeedLevelI * iDir * static.dtReal, 0 - 0.05, static.feedTrimMax)
    endif
    // ANTI-WINDUP above the deadband (rig 7/21): the integral used to FREEZE
    // outside the deadband, so trim wound up during a level trough stayed fat
    // through the overfill it then caused. Level too HIGH -> unwind at normal
    // rate (down-trim is thermally free). Still frozen when LOW: P is pulling
    // there and double-integrating overshot a whole plateau.
    if ( lvlErr < (0 - static.levelDeadML) ) then
        static.feedLevelTrim = clamp(static.feedLevelTrim - static.kFeedLevelI * static.dtReal, 0 - 0.05, static.feedTrimMax)
    endif
    feedLpm = feedFF + levelP + static.feedLevelTrim
endif
// HEAT fill -- to a REDUCED target (mark - fillStopML): cold water expands ~4%
// to boiling and the slew-limited decel keeps delivering; filling to the mark
// itself overshot into the high warn every startup.
if ( fActive and static.haveEvapLevel and (static.mvrPhase == 3) and (static.yEvapLevRaw < (static.evapMidMark - static.fillStopML)) and (feedLpm < (feedFF + static.feedFillLpm)) ) then
    feedLpm = feedFF + static.feedFillLpm
endif
// COLD-FILL CAP (rig 7/22: raw hit 3150 on cold start): fillStopML only ended
// the FILL-RATE segment -- level-P + the trim integral then walked the COLD
// level up to the 2475 mark anyway, and boil-onset swell (+500ml of froth)
// launched from there over the top. In HEAT above the reduced target the feed
// caps at FF (~0): hold the cold charge at mark-fillStopML and let expansion +
// swell carry it the rest -- RUN tops off under the sensors once boiling.
if ( fActive and (static.mvrPhase == 3) and (static.yEvapLevRaw >= (static.evapMidMark - static.fillStopML)) and (feedLpm > feedFF) ) then
    feedLpm = feedFF
endif
// wet/dry-only fallback (no sender): fill far below the mark, then the EvapMid
// switch holds the level via the slow integral -- meter-bias-proof. Trim bound
// stays maxFeedLpm here: with no sender AND no meter the trim IS the feed.
if ( fActive and (static.haveEvapLevel == 0) and (static.feedInvEst < (static.evapMidMark - 250)) ) then
    feedLpm = feedFF + static.feedFillLpm
    static.feedLevelTrim = 0
endif
if ( fActive and (static.haveEvapLevel == 0) and (static.feedInvEst >= (static.evapMidMark - 250)) ) then
    levelErr = 1
    if ( static.yEvapMid ) then
        levelErr = 0 - 1
    endif
    static.feedLevelTrim = clamp(static.feedLevelTrim + static.kFeedLevelI * levelErr * static.dtReal, 0 - 0.05, maxFeedLpm)
    feedLpm = feedFF + static.feedLevelTrim
endif
// COLD-CRASH GUARD (rig 7/13): a max-feed level recovery dumps cold water faster
// than the heaters can carry -- fold the LEVEL-correction terms back to
// production-match as the temp sags. Level can wait; heat can't.
if ( fActive and (static.mvrPhase >= 4) ) then
    coldFold = clamp((static.yEvapTemp - (static.evapTempSetSafe - 8)) / 5, 0, 1)
    feedLpm = feedFF + (feedLpm - feedFF) * coldFold
endif
// MINIMUM RUN FEED (rig 7/15): keep the subcooler's cold sink alive.
if ( fActive and (static.mvrPhase >= 4) and (feedLpm < static.feedMinLpm) ) then
    feedLpm = static.feedMinLpm
endif
// RAW-LOW OVERRIDE (rig 7/21 restart): the SENDER says the level is a plateau+
// below the mark -- believe the physical sensor over every estimate, cap, and
// fold: feed at fill rate on top of FF until the raw reading recovers. Sits
// AFTER the cold-crash fold deliberately: an emptying evaporator (dry heater)
// outranks a temperature sag (the makeup fold-back protects the element).
if ( fActive and (static.mvrPhase >= 4) and (static.yEvapLevRaw < (static.evapLevelSet - static.feedLowRawML)) and (feedLpm < (feedFF + static.feedFillLpm * fCorr)) ) then
    feedLpm = feedFF + static.feedFillLpm * fCorr
endif
// RAW-HIGH THROTTLE (rig 7/21 evening): the sender stepping onto the plateau
// ABOVE the operating edge (2600) means the level has demonstrably crossed the
// mark -- stop topping it off NOW instead of coasting into the 2750 warn: cap
// the feed at HALF production-match so the level drifts back down (~prod/2
// net drain; no cold-slug risk, cuts are thermally free) and bleed the trim at
// 2x (it powered the creep). The 2750 full cut remains the backstop.
if ( fActive and (static.mvrPhase >= 4) and (static.yEvapLevRaw > (static.evapLevelSet + static.feedHighRawML)) ) then
    static.feedLevelTrim = clamp(static.feedLevelTrim - static.kFeedLevelI * 2 * static.dtReal, 0 - 0.05, static.feedTrimMax)
endif
if ( fActive and (static.mvrPhase >= 4) and (static.yEvapLevRaw > (static.evapLevelSet + static.feedHighRawML)) and (feedLpm > (feedFF * (1 - 0.5 * fCorr))) ) then
    feedLpm = feedFF * (1 - 0.5 * fCorr)
endif
// HIGH-LEVEL: stop feeding, let boil-off draw it down -- and BLEED the trim at
// 4x (rig 7/21): every high hit is proof the trim is too fat; without this it
// refilled straight back to 2900.
if ( fActive and (static.yEvapHigh > 0.5) ) then
    feedLpm = 0
    static.feedLevelTrim = clamp(static.feedLevelTrim - static.kFeedLevelI * 4 * static.dtReal, 0 - 0.05, static.feedTrimMax)
endif
// FEED SLEW LIMIT (rig 7/14): rate-limit the command -- every feed slam is a
// cold-water rush the makeup then fights. Sim-scaled dt.
fdt = static.dtReal
if ( static.simEnable ) then
    fdt = static.dtReal * static.simSpeed
endif
// ADAPTIVE BASE LEARNING: EMA of the final commanded feed over feedBaseTau.
// Includes override/cut periods deliberately -- the bang-bang averages to the
// balance rate. Seeded from the first live FF; RUN-time ramp resets outside
// RUN (each run re-proves confidence) while the learned base is retained.
if ( fActive and (static.mvrPhase >= 4) and (static.feedBaseLpm <= 0) and (feedFF > 0) ) then
    static.feedBaseLpm = feedFF
endif
if ( fActive and (static.mvrPhase >= 4) ) then
    static.feedBaseT = static.feedBaseT + fdt
    static.feedBaseLpm = static.feedBaseLpm + (feedLpm - static.feedBaseLpm) * clamp(fdt / static.feedBaseTau, 0, 1)
endif
if ( static.mvrPhase < 4 ) then
    static.feedBaseT = 0
endif
fNew = 0
fHi = 0
fLo = 0
if ( fActive ) then
    fNew = clamp(feedLpm / lpmPerRpm, 0, static.feedRpmMax)
    fHi = static.feedRpmSet + static.feedSlewRpmS * fdt
    fLo = static.feedRpmSet - static.feedSlewRpmS * fdt
endif
if ( fActive and (fNew > fHi) ) then
    fNew = fHi
endif
if ( fActive and (fNew < fLo) ) then
    fNew = fLo
endif
if ( fActive ) then
    static.feedRpmSet = clamp(fNew, 0, static.feedRpmMax)
endif

// ===== MVR PLANT SIMULATOR (blower-throughput-driven) =====
// Closed-loop lumped plant model. PRODUCTION (vapor boil-off) is set by BLOWER
// THROUGHPUT x boiling-readiness -- the compressor is the vapor pump. The
// compressed vapor condenses in the HX and that recovered latent heat (+ comp
// work) boils the next slug, so at steady state the makeup heater only covers
// losses + cold-feed sensible heat and BACKS OFF; blower RPM/bypass sets output.
// Startup: makeup drives the HX up to ~100C (output is mostly steam, no net
// liquid) until it backs off and the cold feed subcools the condensate -- only
// THEN does liquid condensate form and leave. Active only when simEnable=1.

if ( static.simEnable ) then
dt = static.dtReal * static.simSpeed
dt = clamp(dt, 0, 1.0)            // Euler stability guard
dtMin = dt / 60                  // minutes per tick (for ml/min flows)
static.simClock = static.simClock + dt
// slow production SURGE (two incommensurate sines + a little noise)
surge = 1 + static.simSurgeAmp * (sin(static.simClock*0.25) + 0.5*sin(static.simClock*0.83)) + 0.015*randn()
// cold-feed temperature fluctuation
static.simFeedTemp = static.simFeedSupply + static.simFeedNoise * randn()

// ---- effective actuator commands (from the controllers) ----
runOK = static.runSystem and (static.trip == 0)
blowCmd = 0
if ( runOK and (static.mvrPhase >= 3) ) then
    blowCmd = static.blowerCmdRpm      // the soft-start/pressure-guarded command, not the raw target
endif
feedCmd = static.feedCmdRpm
mkDuty = static.makeupDuty
shDuty = static.superDuty
bypass = clamp(static.bypassV / 10, 0, 1)
cpump  = static.condPumpOn

// ---- blower ballistics (motor inertia) ----
static.simBlowerRpm = static.simBlowerRpm + (blowCmd - static.simBlowerRpm) * dt / static.simTauBlower
blowFrac = clamp(static.simBlowerRpm / static.simBlowerRated, 0, 1.5)
compEff  = clamp(blowFrac * (1 - bypass), 0, 1.5)

// ---- PRODUCTION: blower throughput x boiling readiness (the blower IS the
// vapor pump). Nothing boils below ~95C; full at ~100C. Steady-state output
// scales with blower RPM/bypass, NOT with the makeup heater. ----
eT = static.simEvapTemp
boilReady = clamp((eT - 95) / 5, 0, 1)
vaporCap  = compEff * static.simVaporMax
prodTarget = vaporCap * boilReady * surge
static.simProd = static.simProd + (prodTarget - static.simProd) * dt / 2
static.simProd = clamp(static.simProd, 0, 5)
Qboil = static.simProd * static.simLatentPerLpm

// ---- pressures. The blower is the COMPRESSOR: it draws vapor OFF the evaporator
// (SUCTION / low side) and discharges it into the steam chest (HIGH side). The
// condensate / discharge side is vented (catch-tank vent) so it rests near
// atmospheric; the EVAPORATOR is the suction side -- it never goes positive, and the
// instant the blower spins up it is pulled BELOW atmospheric (most while the boil-off
// still lags blower throughput), recovering as the steam chest warms. Blower off
// (warm-up) -> PR=1 -> both sides rest at atmospheric (air + vent). ----
PR = 1 + (static.simPRmax - 1) * compEff
PsatChest = exp((8.14019 - 1810.94 / (244.485 + static.simSteamChest)) * 2.302585) / 51.7149
discharge = max(PsatChest, static.simAtmPress)
static.simSteamPress = static.simSteamPress + (discharge - static.simSteamPress) * dt / static.simTauBlower
static.simSteamPress = clamp(static.simSteamPress, static.simAtmPress, 60)
evapTarget = min(discharge / PR, static.simAtmPress)
static.simEvapPress = static.simEvapPress + (evapTarget - static.simEvapPress) * dt / static.simTauP
static.simEvapPress = clamp(static.simEvapPress, 2, static.simAtmPress)

// ---- superheat from the SH cartridge: the heater W reaching the steam via the
// copper mesh, divided by the vapor heat capacity passing by. With a small 300W
// cartridge and the modest vapor flow this is hugely oversized -> the PWM duty
// sits low (a few %). Less production => less vapor => more superheat per watt. ----
shPower = shDuty * static.simSuperPow * static.simSHmeshEff
vaporKgs = static.simProd / 60
shCap = vaporKgs * static.simSteamCp
shTarget = 0
if ( shCap > 0.5 ) then
    shTarget = clamp(shPower / shCap, 0, 60)
endif
static.simSuperheat = static.simSuperheat + (shTarget - static.simSuperheat) * dt / static.simTauSH
static.simVaporIn = eT + static.simSuperheat

// ---- steam (discharge) side: PR and simSteamPress are computed in the pressures
// block above; it condenses at the saturation temp of simSteamPress (sct, below). ----
// steam chest CONDENSES at the saturation temp of the steam-side pressure
spmm = clamp(static.simSteamPress * 51.7149, 1, 1000000000000)
sct = 1810.94 / (8.14019 - log(spmm) / 2.302585) - 244.485
// HX (steam chest) = 24 lb steel + water with real thermal mass simChx. The
// produced vapor CONDENSES here, releasing its latent heat (+ compressor work);
// simRecovEff of it returns to boil the evaporator. The slab has to warm up
// first (warm-up LAG) before QoutHX can carry the load and makeup can back off.
QinHX = static.simProd * static.simLatentPerLpm * static.simRecovEff
QoutHX = static.simUAsteam * clamp(static.simSteamChest - eT, -200, 200)
static.simSteamChest = clamp(static.simSteamChest + (QinHX - QoutHX) / static.simChx * dt, static.simAmbient, 200)
// (HX-bottom / condensate-outlet temp is computed in the condensate SUBCOOLING
// section below, from the effectiveness-NTU of the subcool HX + its slab mass.)
// vapor OUT = inlet superheat + compression superheat (hotter than condensing temp)
compSH = static.simCompGain * (PR - 1)
voTarget = static.simVaporIn + compSH
static.simVaporOut = static.simVaporOut + (voTarget - static.simVaporOut) * dt / static.simTauBlower

// ---- evaporator energy balance (thermal LAG via simCevap). Qsteam (recovery)
// nearly cancels Qboil at steady state, so the makeup PI only has to cover
// Qfeed + Qloss and BACKS OFF once recovery is established. The cold feed is
// largely preheated by the outgoing condensate (simFeedRegen) -- that heat
// exchange is what subcools the condensate at the bottom of the HX. ----
feedFlow = feedCmd * static.feedStepsPerRev * static.feedLPerStep
// feed preheat = the subcool-HX RECOVERY: the sensible heat the condensate
// dumps into the cold feed (the other side of the same HX). Energy-consistent --
// the condensate loses exactly what the feed gains: feedPre = (cond mass rate /
// feed mass rate) * (condensing temp - subcooled outlet). So the recovery, the
// condensate subcool, and the makeup load are all the same physics.
feedPre = 0
if ( feedFlow > 0.001 ) then
    feedPre = (static.simProd / feedFlow) * clamp(static.simSteamChest - static.simHXbottom, 0, 200)
endif
feedEntry = clamp(static.simFeedTemp + feedPre, static.simFeedTemp, eT)
Qmakeup = mkDuty * static.simMakeupPow
Qsteam = QoutHX
Qfeed = feedFlow * 70 * clamp(eT - feedEntry, 0, 200)
Qloss = static.simUAloss * clamp(eT - static.simAmbient, 0, 300)
Qnet = Qmakeup + Qsteam - Qboil - Qfeed - Qloss
static.simEvapTemp = clamp(eT + (Qnet / static.simCevap) * dt, 0, 160)
// monitoring: instantaneous heat loss + total heat IN (makeup + recovery) (W)
static.simHeatLoss = Qloss
static.simHeatIn = Qmakeup + Qsteam

// ---- evaporator inventory (feed mass balance): feed in vs vapor boiled off ----
blowdownLpm = 0
if ( static.mvrPhase >= 4 ) then
    blowdownLpm = static.blowdownFrac * static.simProd     // concentrate drained via BlowdownValve (L/min)
endif
static.simEvapInv = clamp(static.simEvapInv + (feedFlow*1000 - static.simProd*1000 - blowdownLpm*1000) * dtMin, 0, 8000)

// ---- condensate: liquid only forms once makeup backs off and the cold feed
// subcools it -- the condensate is HOT at startup and cools as the gradient
// develops (simCondTemp). ALL boiled vapor condenses (mass-conserving, so the
// feed-side dead-reckon feedInvEst stays accurate). HX holdup adds the formation
// DELAY; then it fills the tank across the two level sensors. ----
// outlet condensate is LIQUID only when its temp is below boiling (condLiquid,
// the control temp gate). Until then it is STEAM -> vents, none collects, except
// a trim HX (if fitted) condenses trimFrac of it. (feed can absorb ~15%% of the
// steam latent heat it cools.)
feedCoolW = feedFlow * 70 * clamp(100 - static.simFeedTemp, 0, 200)
steamW = static.simProd * static.simLatentPerLpm
trimFrac = 0
if ( static.trimHX and steamW > 1 ) then
    trimFrac = clamp(feedCoolW / steamW, 0, 1)
endif
// ---- condensate collects in the HX bottom TUBE (no separate tank). It forms after
// the holdup delay, drips into the tube, and the pump empties it to DRY. The flow
// meter is on the PUMP OUTLET: it reads the pump-out rate while liquid is moving and
// DROPS TO ~0 the instant the tube runs dry -- the control's empty signal. ----
prodMl = static.simProd * 1000 * trimFrac
if ( static.condLiquid ) then
    prodMl = static.simProd * 1000
endif
static.simCondHold = clamp(static.simCondHold + prodMl * dtMin, 0, static.simCondHoldMax)
flowToTube = 0
if ( static.simCondHold >= static.simCondHoldMax ) then
    flowToTube = prodMl                              // holdup full -> condensate drips into the tube
endif
pumpCap = 0
if ( cpump ) then
    pumpCap = static.simPumpMlMin
endif
avail = static.simCondVol + flowToTube * dtMin       // liquid present + arriving this tick (ml)
pumpedMl = clamp(pumpCap * dtMin, 0, avail)           // can't pump more liquid than is there
static.simCondVol = clamp(static.simCondVol + flowToTube * dtMin - pumpedMl, 0, static.condTubeFullML)
static.simCondHigh = static.simCondVol >= static.condTubeTripML   // point sensor ~3/4 up the tube (runtime, not init-once)
static.simCondLow = static.simCondHigh
// flow meter on the pump OUTLET reads the ACTUAL liquid rate: full pump rate while
// the tube has water, dropping to the incoming TRICKLE (~production) once it is
// sucked dry -- that sustained drop is the control's empty signal. ----
static.simCondFlow = pumpedMl / dtMin / 1000 * static.simFlowCalErr * (1 + static.simFlowNoise * randn())
static.simCondLevel = static.simCondVol / static.condTubeFullML   // 0..1 proxy for charts
static.simCondTotal = static.simCondTotal + pumpedMl / 1000 * static.simFlowCalErr   // SIM totalizer: cumulative liters the METER reads (count/K, carries the meter mis-cal like the rate)

// ---- condensate SUBCOOLING HX (the sensible heat transfer AFTER condensing).
// The cold feed subcools the condensate in a counterflow section; the outlet temp
// is the effectiveness-NTU result of the HX conductance simUAsub and the feed
// flow -- not a fudge. The subcool SLAB has thermal mass (simChxSub): it warms to
// boiling during HEAT, then cools to the computed subcool only as the feed flow
// establishes and pulls its heat out -- so the output is STEAM for a while. ----
feedC = feedFlow / 60 * 4186                       // feed capacity rate (W/degC), feedFlow L/min
NTUsub = static.simUAsub / clamp(feedC, 1, 1000000)
effSub = NTUsub / (1 + NTUsub)                     // balanced counterflow effectiveness
condOutSS = static.simSteamChest - effSub * clamp(static.simSteamChest - static.simFeedTemp, 0, 200)
if ( static.trimHX ) then
    condOutSS = condOutSS - (condOutSS - static.simFeedTemp) * trimFrac
endif
if ( static.mvrPhase < 4 ) then
    static.simHXbottom = static.simSteamChest   // whole HX slab is hot during warm-up (= STEAM at RUN start)
else
    static.simHXbottom = static.simHXbottom + (condOutSS - static.simHXbottom) * clamp(feedC / static.simChxSub * dt, 0, 1)
endif
static.simHXbottom = clamp(static.simHXbottom, static.simAmbient, 200)
static.simCondTemp = static.simHXbottom
// cartridge surface temps for the heater TCs / overheat trips. Makeup tracks the
// boiling water when COVERED; it spikes when the charge drops (uncovered).
coverFrac = clamp(static.simEvapInv / static.simHtrCoverML, 0, 1)
mkSurf = eT + mkDuty * (static.simMakeupCovRise + static.simMakeupRise * (1 - coverFrac))
static.simMakeupHtrTemp = static.simMakeupHtrTemp + (mkSurf - static.simMakeupHtrTemp) * dt / static.simTauHtr
shSurf = static.simVaporIn + shDuty * static.simSuperRise
static.simSuperHtrTemp = static.simSuperHtrTemp + (shSurf - static.simSuperHtrTemp) * dt / static.simTauHtr

// ---- tank-gauge LEVEL SENDER, simulated straight from the MEASURED cal table:
// true inventory (+float bob) -> the plateau SCALED voltage the real AI6 reads
// (slope -1.0/offset 3.68 applied: dry=0V, full ~3.0V). Nonuniform steps, as measured. ----
// gauge vent ties to the evap vapor space (connected-vessel manometer) -- the sender
// reads TRUE level at any evaporator pressure. (The old suction-lie model is gone.)
invB = clamp(static.simEvapInv + static.simLevelBobML * randn(), 0, 3600)
svq = 0
if ( invB >= 100 ) then
    svq = 0.55
endif
if ( invB >= 250 ) then
    svq = 1.2
endif
if ( invB >= 444 ) then
    svq = 1.33
endif
if ( invB >= 719 ) then
    svq = 1.46
endif
if ( invB >= 1025 ) then
    svq = 1.6
endif
if ( invB >= 1350 ) then
    svq = 1.74
endif
if ( invB >= 1700 ) then
    svq = 1.89
endif
if ( invB >= 2000 ) then
    svq = 2.05
endif
if ( invB >= 2225 ) then
    svq = 2.22
endif
if ( invB >= 2475 ) then
    svq = 2.39
endif
if ( invB >= 2750 ) then
    svq = 2.59
endif
if ( invB >= 3025 ) then
    svq = 2.79
endif
if ( invB >= 3325 ) then
    svq = 3.0
endif
static.simEvapSenderV = svq
// ---- demister water (cc). Carryover/condensate collects; the DemisterDrain
// peristaltic pump (demisterDrainOn, set above) bleeds it on a hysteresis. Accumulates
// FAST while warming (wet vapor) and SLOW once hot + superheated, so once everything is
// hot it takes minutes to reach the ~80cc trip. ----
demAccum = static.demisterAccumHot + static.demisterAccumCold * clamp((100 - eT) / 20, 0, 1)
if ( static.runSystem == 0 or eT < 80 ) then
    demAccum = 0
endif
// runaway OVERFILL: past ~3.8L (totally-full HX + fittings) water physically spills
// over into the demister -- the real failure chain is demister fills -> drain can't
// keep up -> FLOOD sensor -> trip. (Spilled volume not debited from simEvapInv --
// only reachable in runaway scenarios.)
if ( static.simEvapInv > static.simSpillML ) then
    demAccum = demAccum + (static.simEvapInv - static.simSpillML) * 2
endif
demPump = static.demisterDrainOn * static.demisterPumpMlMin
static.simDemisterWater = clamp(static.simDemisterWater + (demAccum - demPump) * dtMin, 0, 400)
// flood = the same accumulated level (cc); the flood interlock trips above demisterFloodML
static.simDemisterFlood = static.simDemisterWater >= static.demisterFloodML   // wet/dry FLOOD sensor: dry during normal carryover, wet only on overflow
endif
